const history = [];
function run(redo, undo) { redo(); history.push({ redo, undo }); }

const doc = new Document();
run(() => doc.insert(0, "x"), () => doc.remove(0, 1));
run(doc.save.bind(doc), null);      // detached method needs bind

history.pop()?.undo?.();            // invoker side
